/// Durations, curves and springs. Enter on a critically damped spring, leave faster.
abstract final class LdsMotion {
  static const Duration instant = Duration(milliseconds: 120);
  static const Duration fast = Duration(milliseconds: 160);
  static const Duration exit = Duration(milliseconds: 180);
  static const Duration standard = Duration(milliseconds: 240);
  static const Duration snappy = Duration(milliseconds: 360);
  static const Duration considered = Duration(milliseconds: 480);
  static const Duration smooth = Duration(milliseconds: 560);
  static const Duration momentum = Duration(milliseconds: 600);
  static const Cubic enterCurve = Cubic(0.16, 1, 0.3, 1);
  static const Cubic exitCurve = Cubic(0.7, 0, 0.84, 0);
  static const Cubic standardCurve = Cubic(0.22, 1, 0.36, 1);
  static const Cubic inoutCurve = Cubic(0.65, 0, 0.35, 1);

  /// Presses, toggles, thumbs. No overshoot.
  static final SpringDescription snappySpring =
      SpringDescription.withDampingRatio(mass: 1, stiffness: 541.54);
  static const Duration snappySpringDuration = Duration(milliseconds: 360);

  /// Panels, sheets, sliding indicators, layout. No overshoot.
  static final SpringDescription smoothSpring =
      SpringDescription.withDampingRatio(mass: 1, stiffness: 223.80);
  static const Duration smoothSpringDuration = Duration(milliseconds: 560);

  /// Only after a gesture that carried momentum (a flick). Small overshoot.
  static final SpringDescription momentumSpring =
      SpringDescription.withDampingRatio(
        mass: 1,
        stiffness: 341.51,
        ratio: 0.8,
      );
  static const Duration momentumSpringDuration = Duration(milliseconds: 600);

  static const Map<String, Duration> durations = <String, Duration>{
    'instant': instant,
    'fast': fast,
    'exit': exit,
    'standard': standard,
    'snappy': snappy,
    'considered': considered,
    'smooth': smooth,
  };
  static const Map<String, Cubic> curves = <String, Cubic>{
    'enter': enterCurve,
    'exit': exitCurve,
    'standard': standardCurve,
    'inout': inoutCurve,
  };
}
